/**
 * The 5 fixed demo puzzles of `/puzzles/demo` (P0-01): easy (≤ 600), bundled with the app so the demo works without
 * login and without the puzzle bank. Generated by `scripts/puzzles/lib/seed/build.ts`, validated by
 * `npm run validate:content -- --only puzzles`.
 */
import type { Puzzle } from '@/core/puzzles';
import { puzzleChunkSchema } from '@/core/schemas';
import raw from './demoPuzzles.json';

/** Demo puzzles in display order. */
export const DEMO_PUZZLES: readonly Puzzle[] = puzzleChunkSchema.parse(raw);
